const GameUI=(()=>{
  const C=CognitiveGames;
  const specs={
    memory:{name:'Memory',title:'Sequence garden',glyph:'▦',color:'#9178b8',bg:'#eee7f5',duration:'About 2 minutes',description:'Watch a path light up, then recreate the sequence in the same order.',instructions:['Watch the numbered tiles light up one at a time.','When “Your turn” appears, select the tiles in the same order. Use the buttons or keys 1–9.','There are four rounds with 3, 4, 5, and 6 tiles. Each recall round allows 30 seconds.'],formula:'100 × correctly recalled positions ÷ 18 positions. Every position counts, even if an earlier answer was incorrect.'},
    attention:{name:'Attention',title:'Target watch',glyph:'◎',color:'#5c927a',bg:'#e4f1e9',duration:'About 40 seconds',description:'Stay focused: respond to circles and hold back when a cross appears.',instructions:['Press the Respond button or Space only when you see a circle (○).','Do not respond to a cross (×), or while the display is blank.','There are 20 displays: 12 circles and 8 crosses. Each lasts 1.5 seconds. Responses under 100 ms are anticipations and do not count as hits.'],formula:'50 × (circle hit rate + cross correct-withhold rate). Reaction time is the median of valid circle responses. At least 3 valid hits are needed to save the full assessment.'},
    executive:{name:'Executive function',title:'Rule switch',glyph:'⇄',color:'#7394ad',bg:'#e8eff5',duration:'About 1 minute',description:'Follow the current rule as you switch between number categories.',instructions:['Read the rule above the number on every trial. It can change.','For ODD / EVEN: select Odd or Even. For BELOW / ABOVE 5: select Below 5 or Above 5.','Use the buttons or the left/right arrow keys. There are 16 trials, with 8 rule switches. You have 8 seconds per trial.'],formula:'100 × correct answers ÷ 16 trials. Switch-trial accuracy and median correct response times are reported separately; speed does not change this domain score.'},
    processing:{name:'Processing speed',title:'Symbol match',glyph:'◇',color:'#b4965c',bg:'#f5efdf',duration:'30 seconds',description:'Use the symbol key to match as many symbols as you can, accurately.',instructions:['The key pairs four symbols with the numbers 1–4. It remains visible.','Select the number that matches the large symbol. Use the buttons or keys 1–4.','Work accurately for 30 seconds. Each correct answer adds one point; each error subtracts one.'],formula:'100 × max(0, correct − errors) ÷ 30, capped at 100. The 30-point reference is an arbitrary demo target, not an age norm or clinical cutoff.'}
  };
  let session=null,run=null,root=null;
  const patientById=id=>data.find(p=>p.id===id);
  const today=()=>new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  function ensure(){if(!session)session={patientId:selected,results:{},practiced:{},attempts:{},startedAt:new Date().toISOString(),saved:false};return session;}
  function hub(){const s=ensure(),n=Object.keys(s.results).length,p=patientById(s.patientId);return `<div class="game-intro"><div><h2>Small activities. A fuller picture.</h2><p>Four original interactive tasks, with practice and transparent scoring. Complete all four to save a game-based assessment.</p></div><label class="field">Assessment participant<select class="select" id="game-patient" ${n?'disabled':''}>${data.map(p=>`<option value="${p.id}" ${p.id===s.patientId?'selected':''}>${esc(p.name)} · ${p.id}</option>`).join('')}</select></label></div><div class="game-grid">${Object.entries(specs).map(([k,t])=>`<section class="panel game-card" style="--game-color:${t.color};--game-bg:${t.bg}"><div class="game-card-top"><span class="game-domain"><span class="game-glyph">${t.glyph}</span>${t.name}</span>${s.results[k]?`<span class="score-pill">${s.results[k].score} / 100</span>`:'<span class="protocol-label">Not completed</span>'}</div><h2>${t.title}</h2><p>${t.description}</p><div class="game-meta"><span>${icon('clock')} ${t.duration}</span><span>Keyboard or touch</span></div><p class="game-method">${t.formula}</p><div class="game-card-actions"><button class="button" data-practice="${k}">Practice</button><button class="button primary" data-play="${k}" ${s.saved?'disabled':''}>${s.results[k]?'Retake activity':'Start activity'}</button>${s.results[k]?`<button class="text-button" data-result="${k}">View result</button>`:''}</div></section>`).join('')}</div><section class="panel game-save"><div><h2>${s.saved?'Assessment saved':n+' of 4 activities completed'}</h2><p>${esc(p?.name||'Select a participant')} · Protocol Games v1<br>${s.saved?'Start a new session for another assessment.':'Scores stay in this tab until you save. A retake replaces the previous result; it does not select your best score.'}</p>${n?`<div class="session-scores">${Object.entries(s.results).map(([k,r])=>`<span>${specs[k].name}: ${r.score}</span>`).join('')}</div>`:''}</div><div class="game-card-actions"><button class="button" id="game-reset">${s.saved?'New session':'Reset session'}</button><button class="button primary" id="game-summary" ${n!==4||s.saved?'disabled':''}>Review & save assessment</button></div></section><p class="form-note">Original, unvalidated demonstration activities. These scores describe task performance, not cognitive impairment, IQ, or population percentiles. Use the same device, input method and conditions for follow-up. Visual or motor difficulties can affect results. Switching tabs interrupts an active activity. Manual scores and Games v1 scores have separate baselines.</p>`;}
  function bind(){const select=document.querySelector('#game-patient');if(select)select.onchange=()=>{session.patientId=select.value;selected=select.value;};document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>intro(b.dataset.practice,true));document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>intro(b.dataset.play,false));document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showResult(b.dataset.result,session.results[b.dataset.result],false));const summary=document.querySelector('#game-summary');if(summary)summary.onclick=showSummary;const reset=document.querySelector('#game-reset');if(reset)reset.onclick=()=>{if(!Object.keys(session.results).length||session.saved){session=null;render();return;}openShell('New session','Unsaved activity scores');stage(`<h1>Start a new session?</h1><p>This clears the current unsaved activity results. Saved patient records are kept.</p><div class="game-responses"><button id="keep-session">Keep results</button><button id="discard-session">Start new session</button></div>`);document.querySelector('#keep-session').onclick=close;document.querySelector('#discard-session').onclick=()=>{session=null;close();render();};};}
  function openShell(title,sub){if(!root){root=document.createElement('div');root.id='game-root';document.body.append(root);}document.querySelector('#app').inert=true;document.body.style.overflow='hidden';root.innerHTML=`<section class="game-shell" role="dialog" aria-modal="true" aria-labelledby="game-title"><header class="game-top"><div><h2 id="game-title">${esc(title)}</h2><p>${esc(sub)}</p></div><button class="button" id="game-exit">Close</button></header><div class="game-progress"><span id="game-progress" style="width:0%"></span></div><main class="game-stage" id="game-stage"></main><footer class="game-bottom">CognitiveTrack · Games v1 · Task performance only; not a diagnostic assessment</footer></section>`;document.querySelector('#game-exit').onclick=()=>{if(run?.running){interrupt('Activity stopped','This attempt was not scored. Completed activities remain in your session.');}else close();};}
  function stage(html){document.querySelector('#game-stage').innerHTML=html;document.querySelector('#game-stage h1')?.setAttribute('tabindex','-1');document.querySelector('#game-stage h1')?.focus();}
  function cleanup(){if(run){run.running=false;run.timers.forEach(clearTimeout);run.timers=[];run.key=null;}}
  function close(){cleanup();run=null;root?.remove();root=null;document.querySelector('#app').inert=false;document.body.style.overflow='';if(page==='Activities')render();}
  function later(fn,ms){const token=run;const id=setTimeout(()=>{if(run===token&&run.running)fn();},ms);run.timers.push(id);return id;}
  function progress(n,total){document.querySelector('#game-progress').style.width=`${100*n/total}%`;}
  function intro(key,practice){ensure();if(session.saved&&!practice)return;cleanup();run=null;const t=specs[key];openShell(t.name+' · '+t.title,(practice?'Unscored practice':'Scored activity')+' · '+patientById(session.patientId)?.name);stage(`<p class="game-phase">${practice?'Practice mode':'Before you begin'}</p><h1>${t.title}</h1><p>${t.description}</p><div class="game-instructions"><ul>${t.instructions.map(i=>`<li>${i}</li>`).join('')}</ul></div><div class="notice"><strong>How your score is calculated</strong><br>${t.formula}</div>${!practice&&!session.practiced[key]?'<p class="game-hint">Try the short practice first. Practice does not affect your score.</p>':''}<div class="game-responses">${!practice&&!session.practiced[key]?'<button id="practice-first">Try practice</button>':''}<button id="begin-game">${practice?'Begin practice':session.results[key]?'Begin replacement attempt':'Begin scored activity'}</button></div><p class="game-hint">Sit comfortably, use your usual visual aids, and keep this tab visible. Timed activities cannot be paused.</p>`);document.querySelector('#begin-game').onclick=()=>begin(key,practice);const p=document.querySelector('#practice-first');if(p)p.onclick=()=>intro(key,true);}
  function begin(key,practice){cleanup();run={keyName:key,practice,running:true,timers:[],trials:[],key:null,inputMethod:new Set(),startedAt:new Date().toISOString()};if(!practice)session.attempts[key]=(session.attempts[key]||0)+1;openShell(specs[key].name+' · '+specs[key].title,(practice?'Practice · not scored':'Scored activity')+' · '+patientById(session.patientId)?.name);({memory:memoryStart,attention:attentionStart,executive:executiveStart,processing:processingStart})[key]();}
  function interrupt(title,message){const key=run?.keyName,practice=run?.practice;cleanup();stage(`<div class="game-abort"><p class="game-phase">Attempt not saved</p><h1>${esc(title)}</h1><p>${esc(message)}</p><div class="game-responses"><button id="game-retry">Restart activity</button><button id="game-return">Return to activities</button></div></div>`);document.querySelector('#game-retry').onclick=()=>intro(key,practice);document.querySelector('#game-return').onclick=close;}
  function finish(result){const key=run.keyName,practice=run.practice;result={...result,protocol:C.protocol,startedAt:run.startedAt,completedAt:new Date().toISOString(),inputMethods:[...run.inputMethod],attemptNumber:session.attempts[key]||0};cleanup();if(practice)session.practiced[key]=true;else session.results[key]=result;showResult(key,result,practice);}
  function memoryStart(){run.lengths=run.practice?[3]:[3,4,5,6];run.round=0;run.rounds=[];memoryRound();}
  function memoryRound(){const length=run.lengths[run.round];run.sequence=C.shuffle([1,2,3,4,5,6,7,8,9]).slice(0,length);run.responses=[];run.recalling=false;progress(run.round,run.lengths.length);stage(`<p class="game-phase">${run.practice?'Practice':'Round '+(run.round+1)+' of '+run.lengths.length} · ${length} tiles</p><h1 id="memory-prompt">Watch the sequence</h1><p id="memory-help">Remember the order. Wait until it is your turn.</p><div class="sequence-grid">${Array.from({length:9},(_,i)=>`<button class="sequence-tile" data-tile="${i+1}" aria-label="Tile ${i+1}" disabled>${i+1}</button>`).join('')}</div><div class="response-slots">${Array.from({length},()=>'<span class="response-slot">·</span>').join('')}</div><p class="game-hint" id="memory-count">Get ready…</p>`);document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>memoryAnswer(Number(b.dataset.tile),'pointer'));run.key=e=>{if(/^[1-9]$/.test(e.key))memoryAnswer(Number(e.key),'keyboard');};let i=0;function light(){if(i===length){run.recalling=true;document.querySelector('#memory-prompt').textContent='Your turn';document.querySelector('#memory-help').textContent='Select the tiles in the order you saw them.';document.querySelector('#memory-count').textContent='30 seconds to recall · use keys 1–9 or the tiles';document.querySelectorAll('[data-tile]').forEach(b=>b.disabled=false);run.recallStart=performance.now();run.recallTimer=later(memoryRoundEnd,30000);return;}const tile=document.querySelector(`[data-tile="${run.sequence[i]}"]`);tile.classList.add('lit');tile.setAttribute('aria-label','Tile '+run.sequence[i]+' highlighted');document.querySelector('#memory-count').textContent=`Watch · ${i+1} of ${length}`;later(()=>{tile.classList.remove('lit');tile.setAttribute('aria-label','Tile '+run.sequence[i]);i++;later(light,300);},650);}later(light,700);}
  function memoryAnswer(n,method){if(!run?.running||!run.recalling)return;if(performance.now()-run.recallStart>=30000){memoryRoundEnd();return;}run.inputMethod.add(method);run.responses.push(n);document.querySelectorAll('.response-slot')[run.responses.length-1].textContent=n;if(run.responses.length===run.sequence.length)memoryRoundEnd();}
  function memoryRoundEnd(){if(!run.recalling)return;run.recalling=false;clearTimeout(run.recallTimer);run.rounds.push({expected:run.sequence.slice(),responses:run.responses.slice(),recallMs:Math.round(performance.now()-run.recallStart)});run.round++;if(run.round===run.lengths.length){finish(C.memory(run.rounds));return;}document.querySelectorAll('[data-tile]').forEach(b=>b.disabled=true);document.querySelector('#memory-prompt').textContent='Round complete';document.querySelector('#memory-help').textContent='Take a moment. The next sequence is one tile longer.';document.querySelector('#memory-count').innerHTML='<button class="button primary" id="memory-next">Next round</button>';document.querySelector('#memory-next').onclick=memoryRound;}
  function attentionStart(){run.deck=run.practice?[true,false,true,false]:C.shuffle([...Array(12).fill(true),...Array(8).fill(false)]);run.index=0;run.trials=[];run.current=null;stage(`<p class="game-phase" id="trial-progress">Get ready</p><h1>Circle: respond. Cross: wait.</h1><p class="game-hint">Press once per circle. Do not respond to a cross or a blank display.</p><div class="target-area"><span class="stimulus" id="attention-stimulus">·</span></div><button class="button primary" id="attention-response" style="min-height:62px;min-width:220px;margin:0 auto">Respond to circle <span style="opacity:.7">[Space]</span></button><p class="practice-feedback" id="attention-feedback" aria-live="polite"></p>`);document.querySelector('#attention-response').onclick=()=>attentionAnswer('pointer');run.key=e=>{if(e.code==='Space')attentionAnswer('keyboard');};later(attentionTrial,700);}
  function attentionTrial(){if(run.index===run.deck.length){finish(C.attention(run.trials));return;}progress(run.index,run.deck.length);document.querySelector('#trial-progress').textContent=`${run.practice?'Practice':'Display'} ${run.index+1} of ${run.deck.length}`;const stimulus=document.querySelector('#attention-stimulus');stimulus.textContent=run.deck[run.index]?'○':'×';stimulus.classList.toggle('distractor',!run.deck[run.index]);run.current=null;const token=run;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(run!==token||!run.running)return;const start=performance.now();run.current={target:run.deck[run.index],responded:false,rt:null,start};later(()=>{if(performance.now()-start>1800){interrupt('Timing was interrupted','The browser could not maintain the display timing. Please restart this activity in an active tab.');return;}const current=run.current;run.trials.push({target:current.target,responded:current.responded,rt:current.rt});run.current=null;stimulus.textContent='';if(run.practice)document.querySelector('#attention-feedback').textContent=current.target?(current.responded&&current.rt>=100?'Circle detected.':current.responded?'Too early — wait until you see the circle.':'That circle needed a response.'):(current.responded?'That was a cross. Wait on crosses.':'Correct — no response to the cross.');run.index++;later(attentionTrial,300);},1500);}));}
  function attentionAnswer(method){const t=run?.current;if(!run?.running||!t||t.responded)return;const rt=performance.now()-t.start;if(rt>1500)return;t.responded=true;t.rt=Math.round(rt);run.inputMethod.add(method);}
  function executiveStart(){run.deck=C.executiveDeck(run.practice);run.index=0;run.trials=[];executiveTrial();}
  function executiveTrial(){if(run.index===run.deck.length){finish(C.executive(run.trials));return;}const t=run.deck[run.index];progress(run.index,run.deck.length);stage(`<p class="game-phase">${run.practice?'Practice':'Trial'} ${run.index+1} of ${run.deck.length}</p><h1>Follow the current rule</h1><div class="rule-tag ${t.rule}">${t.rule==='parity'?'ODD / EVEN':'BELOW / ABOVE 5'}</div><div class="game-number">${t.number}</div><div class="game-responses"><button id="executive-left">${t.rule==='parity'?'Odd':'Below 5'}<kbd>Left arrow key</kbd></button><button id="executive-right">${t.rule==='parity'?'Even':'Above 5'}<kbd>Right arrow key</kbd></button></div><p class="game-hint">8 seconds per trial · Check the rule before answering</p><p class="practice-feedback" id="executive-feedback" aria-live="polite"></p>`);run.accepting=false;const token=run;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(run!==token||!run.running)return;run.trialStart=performance.now();run.accepting=true;run.trialTimeout=later(()=>executiveAnswer(null,'timeout'),8000);}));document.querySelector('#executive-left').onclick=()=>executiveAnswer('left','pointer');document.querySelector('#executive-right').onclick=()=>executiveAnswer('right','pointer');run.key=e=>{if(e.key==='ArrowLeft')executiveAnswer('left','keyboard');if(e.key==='ArrowRight')executiveAnswer('right','keyboard');};}
  function executiveAnswer(answer,method){if(!run?.running||!run.accepting)return;const elapsed=performance.now()-run.trialStart;if(elapsed>8500){interrupt('Timing was interrupted','Please restart this activity with this tab active.');return;}run.accepting=false;clearTimeout(run.trialTimeout);if(elapsed>8000)answer=null;const t=run.deck[run.index];run.trials.push({...t,answer,rt:Math.round(elapsed)});if(answer)run.inputMethod.add(method);document.querySelectorAll('.game-responses button').forEach(b=>b.disabled=true);if(run.practice)document.querySelector('#executive-feedback').textContent=answer===t.expected?'Correct.':answer===null?'Time ran out.':'Check the rule — the other choice was correct.';run.index++;later(executiveTrial,run.practice?900:350);}
  const symbols=['○','◇','△','□'];
  function processingStart(){run.mapping=C.shuffle([1,2,3,4]);run.trials=[];run.duration=run.practice?10000:30000;run.previous=-1;run.accepting=false;stage(`<p class="game-phase">${run.practice?'10-second practice':'30-second activity'}</p><h1>Match the symbol</h1><div class="symbol-key">${symbols.map((s,i)=>`<div class="symbol-pair"><span>${s}</span><strong>${run.mapping[i]}</strong></div>`).join('')}</div><div class="timer-display" id="speed-time">${run.duration/1000} seconds remaining</div><div class="speed-target" id="speed-symbol"></div><div class="speed-answers">${[1,2,3,4].map(n=>`<button data-speed="${n}" aria-label="Answer ${n}">${n}</button>`).join('')}</div><p class="game-hint">Use the key above · Select a number or press keys 1–4</p><p class="practice-feedback" id="speed-feedback" aria-live="polite"></p>`);document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>processingAnswer(Number(b.dataset.speed),'pointer'));run.key=e=>{if(/^[1-4]$/.test(e.key))processingAnswer(Number(e.key),'keyboard');};run.deadline=performance.now()+run.duration;processingTrial();function tick(){const remaining=run.deadline-performance.now();document.querySelector('#speed-time').textContent=`${Math.max(0,Math.ceil(remaining/1000))} seconds remaining`;if(remaining<=0){if(remaining< -750){interrupt('Timing was interrupted','This attempt was not scored because the timer was interrupted. Please restart.');return;}finish(C.processing(run.trials));}else later(tick,100);}later(tick,100);}
  function processingTrial(){const options=[0,1,2,3].filter(i=>i!==run.previous),index=options[Math.floor(Math.random()*options.length)];run.previous=index;run.expected=run.mapping[index];run.accepting=false;document.querySelector('#speed-symbol').textContent=symbols[index];const token=run;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(run!==token||!run.running)return;run.trialStart=performance.now();run.accepting=true;}));}
  function processingAnswer(answer,method){if(!run?.running||!run.accepting)return;if(performance.now()>=run.deadline)return;run.accepting=false;const rt=Math.round(performance.now()-run.trialStart);run.trials.push({symbol:symbols[run.previous],expected:run.expected,answer,rt});run.inputMethod.add(method);if(run.practice)document.querySelector('#speed-feedback').textContent=answer===run.expected?'Matched.':'Check the key for that symbol.';processingTrial();}
  function metrics(key,r){if(key==='memory')return [[r.correct+'/'+r.total,'Positions recalled'],[r.rounds.length,'Rounds completed'],[Math.max(...r.rounds.filter(x=>x.expected.every((v,i)=>x.responses[i]===v)).map(x=>x.expected.length),0),'Longest perfect sequence']];if(key==='attention')return [[r.hits+'/'+r.targets,'Circle hits'],[r.falseAlarms,'False alarms'],[r.reaction===null?'—':r.reaction+' ms','Median valid reaction']];if(key==='executive')return [[r.correct+'/'+r.total,'Correct answers'],[r.switchCorrect+'/'+r.switchTotal,'Rule-switch accuracy'],[r.switchMedian===null?'—':r.switchMedian+' ms','Median correct switch']];return [[r.correct,'Correct matches'],[r.errors,'Errors'],[r.total,'Responses']];}
  function showResult(key,r,practice){cleanup();openShell(specs[key].name+' · Result',practice?'Unscored practice':'Current session result');progress(1,1);stage(`<p class="game-phase">${practice?'Practice complete':'Activity complete'}</p><h1>${practice?'Ready when you are.':'Your '+specs[key].name.toLowerCase()+' result'}</h1>${practice?'<p>Practice is not included in the saved assessment.</p>':`<div class="result-score"><strong>${r.score}</strong><span>task score / 100</span></div>`}<div class="result-metrics">${metrics(key,r).map(([v,l])=>`<div><b>${v}</b>${l}</div>`).join('')}</div>${key==='attention'?`<p>${r.misses} misses · ${r.anticipations} early responses · ${r.validReactions} valid reaction samples</p>${!practice&&r.validReactions<3?'<div class="notice">Complete attention again with at least 3 valid circle responses before saving a full assessment. Missing reaction time is never replaced with an invented value.</div>':''}`:''}<div class="notice"><strong>Scoring</strong><br>${specs[key].formula}<br><br>This is an unvalidated task score. It is not a percentile, diagnosis, or severity label.</div><div class="game-responses">${practice&&!session.saved?'<button id="after-practice">Start scored activity</button>':''}<button id="back-activities">Return to activities</button></div>`);document.querySelector('#back-activities').onclick=close;const start=document.querySelector('#after-practice');if(start)start.onclick=()=>intro(key,false);}
  function showSummary(){const s=ensure();if(Object.keys(s.results).length!==4||s.saved)return;cleanup();run=null;openShell('Review & save assessment',patientById(s.patientId)?.name+' · Games v1');stage(`<p class="game-phase">All four activities complete</p><h1>Review your session</h1><p>These scores will be saved to ${esc(patientById(s.patientId)?.name)}’s timeline as a separate assessment protocol.</p><div class="table-wrap"><table class="game-summary-table"><thead><tr><th>Domain</th><th>Score</th><th>Raw result</th></tr></thead><tbody>${Object.entries(s.results).map(([k,r])=>`<tr><td>${specs[k].name}</td><td>${r.score}/100</td><td>${metrics(k,r).slice(0,2).map(([v,l])=>`${l}: ${v}`).join(' · ')}</td></tr>`).join('')}</tbody></table></div><p>Attention reaction time: ${s.results.attention.reaction===null?'unavailable':s.results.attention.reaction+' ms'} · Composite: ${Math.round(Object.values(s.results).reduce((a,r)=>a+r.score,0)/4)}/100</p><div class="notice">The first saved Games v1 session establishes a new baseline. The existing manually entered sample scores remain in history and are not mixed into this trajectory. Retakes can introduce practice effects; attempt counts and raw responses are retained in the JSON backup.</div><form id="save-games"><div class="game-save-fields"><label class="field">Assessment date<input name="date" type="date" value="${today()}" readonly required></label><label class="field">Testing conditions<input name="context" maxlength="250" placeholder="Device, input method, sleep, distractions" required></label><label class="field full">Session notes<textarea name="notes" maxlength="2000" placeholder="Observations and follow-up considerations"></textarea></label></div><p id="game-save-error" role="alert" style="color:#a66e45"></p><div class="game-responses"><button type="submit" id="save-game-record" ${s.results.attention.validReactions<3?'disabled':''}>Save to patient timeline</button></div></form>${s.results.attention.validReactions<3?'<p class="notice">Attention needs at least 3 valid circle responses. Return to activities and retake attention.</p>':''}`);document.querySelector('#save-games').onsubmit=e=>{e.preventDefault();save(new FormData(e.target));};}
  function save(form){const s=session,p=patientById(s.patientId),date=form.get('date');if(s.saved||!p)return;if(p.records.some(r=>r.date===date&&r.protocol===C.protocol)){document.querySelector('#game-save-error').textContent='A Games v1 assessment already exists for this patient today. These results are still available in the session. Only one Games v1 record per day can be saved.';return;}if(s.results.attention.validReactions<3)return;const context=form.get('context').trim();if(!context){document.querySelector('#game-save-error').textContent='Please describe the testing conditions.';return;}const raw=structuredClone(s.results);const notes=[form.get('notes').trim(),...Object.entries(raw).map(([k,r])=>`${specs[k].name}: ${r.score}/100; ${metrics(k,r).map(([v,l])=>`${l} ${v}`).join('; ')}; scored attempts ${s.attempts[k]||1}.`)].filter(Boolean).join('\n');const record={date,protocol:C.protocol,completedAt:new Date().toISOString(),reaction:s.results.attention.reaction,context,notes,gameResults:raw,attemptCounts:{...s.attempts}};Object.keys(specs).forEach(k=>record[k]=s.results[k].score);p.records.push(record);p.records.sort((a,b)=>a.date.localeCompare(b.date)||(a.completedAt||'').localeCompare(b.completedAt||''));Object.keys(reviewed).filter(k=>k.startsWith(p.id+'-')).forEach(k=>delete reviewed[k]);selected=p.id;if(!persist()){p.records=p.records.filter(r=>r!==record);document.querySelector('#game-save-error').textContent='Browser storage failed. Your results remain in this session. Free storage space and try again.';return;}s.saved=true;close();page='Overview';render();toast('Games v1 assessment saved. Its own baseline and trajectory are ready.');}
  document.addEventListener('keydown',e=>{if(!root)return;if(e.key==='Escape'){e.preventDefault();document.querySelector('#game-exit')?.click();return;}if(e.key==='Tab'){const controls=[...root.querySelectorAll('button,input,select,textarea')].filter(b=>!b.disabled);if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0]?.focus();}return;}if(run?.running&&run.key&&!e.repeat&&!e.ctrlKey&&!e.metaKey&&!e.altKey){if(['Space','ArrowLeft','ArrowRight'].includes(e.code)||/^[1-9]$/.test(e.key)){e.preventDefault();run.key(e);}}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&run?.running)interrupt('Activity interrupted','You left the active tab. To avoid mixing interrupted timing with task performance, this attempt was not scored. Restart when you are ready.');});
  window.addEventListener('beforeunload',e=>{if(run?.running||(session&&!session.saved&&Object.keys(session.results).length)){e.preventDefault();e.returnValue='';}});
  return {hub,bind,intro,showSummary};
})();

